'use strict';
const {
  Model
} = require('sequelize');
module.exports = (sequelize, DataTypes) => {
  class products extends Model {
    /**
     * Helper method for defining associations.
     * This method is not a part of Sequelize lifecycle.
     * The `models/index` file will call this method automatically.
     */
    static associate(models) {
      // define association here
      products.belongsTo(models.brands,{
        foreignKey: 'brand_id'
      })
      products.belongsTo(models.categories,{
        foreignKey: 'category_id'
      })
      products.hasMany(models.order_detail, {
        foreignKey: 'product_id'
      })
      products.hasMany(models.bannerdetail, {
        foreignKey: 'product_id'
      })
      products.hasMany(models.newdetail, {
        foreignKey: "product_id",
      });
      products.hasMany(models.feedback, {
         foreignKey: "product_id",
      });
      products.hasMany(models.product_image,{
        foreignKey: 'product_id',
        as: 'product_image'//thêm bí danh as để sử dụng trong truy vấn
      })
      products.hasMany(models.cart_items,{
        foreignKey: 'product_id'
      })
      products.hasMany(models.ProductAttributes, {
        foreignKey: 'product_id'
      });
       products.hasMany(models.product_variant_values, {
         foreignKey: "product_id",
       });
    }
  }
  products.init({
    name: DataTypes.STRING,
    image: DataTypes.STRING,
    price: DataTypes.INTEGER,
    description: DataTypes.STRING,
    oldprice: DataTypes.INTEGER,
    specification: DataTypes.STRING,
    buyturn: DataTypes.INTEGER,
    quanity: DataTypes.INTEGER,
    brand_id: DataTypes.INTEGER,
    category_id: DataTypes.INTEGER
  }, {
    sequelize,
    modelName: 'products',

  });
  return products;
};

