sourcesContent:
"use strict";
const { Model } = require("sequelize");

module.exports = (sequelize, DataTypes) => {
  class products extends Model {
    static associate(models) {
      // Gọi đúng tên model gốc được sinh ra từ các lệnh CLI của bạn
      products.belongsTo(models.brands, { foreignKey: "brand_id" });
      products.belongsTo(models.categories, { foreignKey: "category_id" });

      // Chú ý: Lệnh CLI tạo model chi tiết đơn hàng của bạn là '--name order-detail'
      // nên Sequelize sẽ map thành tên đối tượng là models['order-detail'] hoặc models.order_detail
      const OrderDetailModel = models["order-detail"] || models.order_detail;
      if (OrderDetailModel) {
        products.hasMany(OrderDetailModel, { foreignKey: "product_id" });
      }

      if (models.bannerdetail)
        products.hasMany(models.bannerdetail, { foreignKey: "product_id" });
      if (models.newdetail)
        products.hasMany(models.newdetail, { foreignKey: "product_id" });
      if (models.feedback)
        products.hasMany(models.feedback, { foreignKey: "product_id" });
      if (models.cart_items)
        products.hasMany(models.cart_items, { foreignKey: "product_id" });

      if (models.ProductAttributes)
        products.hasMany(models.ProductAttributes, {
          foreignKey: "product_id",
          as: "ProductAttributes",
        });

      // Tìm kiếm linh hoạt mọi khả năng đặt tên model biến thể trong mảng models
      const ProductVariantValuesModel =
        models.product_variant_values ||
        models.ProductVariantValues ||
        models.productVariantValues ||
        models.Product_variant_values;

      if (ProductVariantValuesModel) {
        products.hasMany(ProductVariantValuesModel, {
          foreignKey: "product_id",
          as: "product_variant_values", // Giữ nguyên Alias chữ thường để khớp với API của bạn
        });
        console.log(
          ">>> Đã kích hoạt liên kết product_variant_values thành công!",
        );
      } else {
        console.log(
          ">>> CẢNH BÁO: Không tìm thấy model biến thể trong hệ thống Backend!",
        );
      }

      // ── GIẢI PHÁP ĐỒNG BỘ ẢNH SẢN PHẨM ──
      if (models.product_image || models.product_images) {
        const ImageModel = models.product_image || models.product_images;

        // Khai báo cả phiên bản số ít (Tránh lỗi Alias so khớp của Sequelize)
        products.hasMany(ImageModel, {
          foreignKey: "product_id",
          as: "product_image",
        });

        // Khai báo dự phòng phiên bản số nhiều (Tránh lỗi câu lệnh Controller cũ)
        products.hasMany(ImageModel, {
          foreignKey: "product_id",
          as: "product_images",
        });
      }
    }
  }

  products.init(
    {
      name: DataTypes.STRING,
      image: DataTypes.STRING,
      price: DataTypes.INTEGER,
      description: {
        type: DataTypes.TEXT, // Đổi từ STRING sang TEXT nếu trước đó đang để STRING
        allowNull: true,
      },
      oldprice: DataTypes.INTEGER,
      specification: DataTypes.STRING,
      buyturn: DataTypes.INTEGER,
      quanity: DataTypes.INTEGER,
      brand_id: DataTypes.INTEGER,
      category_id: DataTypes.INTEGER,
      // 🌟 ĐÃ BỔ SUNG: Khai báo trường user_id để Sequelize không lọc bỏ khi insert
      user_id: {
        type: DataTypes.INTEGER,
        allowNull: true,
      },
    },
    {
      sequelize,
      modelName: "products", // Đúng tên gốc khi bạn chạy lệnh model:generate
      tableName: "products", // Khớp đúng bảng trong DB của bạn
      timestamps: true,
      underscored: true, // Bắt buộc để nhận diện gạch dưới _
      createdAt: "created_at",
      updated_at: "updated_at",
    },
  );

  return products;
};

