const Sequelize = require("sequelize");
const db = require("../models");
const OrderStatus = require("../constants");
const Op = Sequelize.Op;

// 1. LẤY DANH SÁCH TẤT CẢ GIỎ HÀNG (Đã bỏ kết nối biến thể lỗi)
async function getCarts(req, res) {
  const { page = 1 } = req.query;

  const pageSize = 5;
  const offset = (page - 1) * pageSize;

  const [carts, total] = await Promise.all([
    db.carts.findAll({
      limit: pageSize,
      offset,
      include: [
        {
          model: db.cart_items,
          as: "cart_items",
          // 🌟 ÉP CHỈ LẤY CỘT HỢP PHÁP TRONG DB
          attributes: ["id", "cart_id", "product_id", "quanity"],
          include: [
            {
              model: db.products,
              as: "products",
            },
            // 🔥 ĐÃ XÓA: Bỏ hoàn toàn phần include biến thể ở đây
          ],
        },
      ],
    }),

    db.carts.count(),
  ]);

  return res.status(200).json({
    message: "Lấy danh sách giỏ hàng thành công",
    data: carts,
    currentPage: Number(page),
    totalPages: Math.ceil(total / pageSize),
    total,
  });
}

// 2. LẤY CHI TIẾT GIỎ HÀNG THEO ID (Đã loại bỏ cột thừa để hết lỗi 500)
async function getCartById(req, res) {
  const { id } = req.params;

  const cart = await db.carts.findOne({
    where: { id },
    include: [
      {
        model: db.cart_items,
        as: "cart_items",
        // 🌟 CHỖ SAI ĐÃ SỬA: Thêm attributes để ép Sequelize KHÔNG tự động SELECT cột 'product_variant_value_id' không tồn tại trong DB
        attributes: ["id", "cart_id", "product_id", "quanity", "created_at", "updated_at"],
        include: [
          {
            model: db.products,
            as: "products",
          },
          // 🔥 CHỖ SAI ĐÃ SỬA: Xóa bỏ hoàn toàn model 'db.product_variant_values' ở đây vì bảng này không liên kết với `cart_items` trong DB của bạn
        ],
      },
    ],
  });
  if (!cart) {
    return res.status(404).json({
      message: "giỏ hàng không tồn tại",
    });
  }

  return res.status(200).json({
    message: "Lấy giỏ hàng thành công",
    data: cart,
  });
}

async function insertCart(req, res) {
  const { id, user_id, session_id } = req.body;

  let existingCart = null;

  if (id) {
    existingCart = await db.carts.findOne({
      where: { id },
    });
  }

  if (existingCart) {
    existingCart.user_id = user_id;
    existingCart.session_id = session_id;

    await existingCart.save();

    return res.status(200).json({
      message: "Cập nhật giỏ hàng thành công",
      data: existingCart,
    });
  }

  const [newCart, created] = await db.carts.findOrCreate({
    where: { user_id },
    defaults: {
      user_id,
      session_id,
    },
  });

  return res.status(201).json({
    message: "Thêm giỏ hàng thành công",
    data: newCart,
  });
}
// 3. CHECKOUT AN TOÀN TRỰC TIẾP QUA SẢN PHẨM GỐC
async function checkoutCart(req, res) {
  const {
    cart_id,
    product_id,
    variant_id, // 🔥 BỔ SUNG: Nhận thêm variant_id (hoặc tên cột tương ứng bên bạn)
    quanity,
    quantity,
    total,
    note,
    phone,
    address,
    user_id,
    session_id,
  } = req.body;

  const transaction = await db.sequelize.transaction();

  try {
    let orderDetails = [];
    let finalTotal = total || 0;
    const isBuyNow = !!product_id;
    const inputQuantity = parseInt(quantity || quanity) || 1;

    // Xác định Model Biến thể linh hoạt theo cấu hình DB của bạn
    const VariantModel = db.product_variant_values || db.ProductVariantValues || db.productVariantValues;

    if (isBuyNow) {
      // =========================================================================
      // LUỒNG 1: MUA NGAY TRỰC TIẾP
      // =========================================================================
      let itemPrice = 0;

      // 1.1 Nếu mua kèm Biến thể (Variant)
      if (variant_id && VariantModel) {
        const variant = await VariantModel.findOne({
          where: { id: variant_id, product_id: product_id },
          transaction,
        });

        if (!variant) {
          await transaction.rollback();
          return res.status(404).json({ message: `Biến thể sản phẩm không tồn tại` });
        }

        if (variant.stock < inputQuantity) {
          await transaction.rollback();
          return res.status(400).json({ message: `Biến thể phân loại này không đủ số lượng trong kho (Còn lại: ${variant.stock})` });
        }

        itemPrice = variant.price;

        orderDetails.push({
          product_id: product_id,
          variant_id: variant.id, // Lưu thêm variant_id vào detail nếu bảng order_details của bạn có cột này
          quantity: inputQuantity,
          price: itemPrice,
        });

        // Trừ kho của bảng Biến thể
        await VariantModel.update(
          { stock: variant.stock - inputQuantity },
          { where: { id: variant.id }, transaction }
        );

      } else {
        // 1.2 Nếu mua Sản phẩm thường (Không có biến thể)
        const product = await db.products.findOne({
          where: { id: product_id },
          attributes: ["id", "name", "price", "quanity"],
          raw: true,
          transaction,
        });

        if (!product) {
          await transaction.rollback();
          return res.status(404).json({ message: `Sản phẩm ID ${product_id} không tồn tại` });
        }

        if (product.quanity < inputQuantity) {
          await transaction.rollback();
          return res.status(400).json({ message: `Sản phẩm ${product.name} không đủ số lượng trong kho` });
        }

        itemPrice = product.price;

        orderDetails.push({
          product_id: product.id,
          quantity: inputQuantity,
          price: itemPrice,
        });

        // Trừ kho hàng gốc của sản phẩm thường
        await db.products.update(
          { quanity: product.quanity - inputQuantity },
          { where: { id: product.id }, transaction }
        );
      }

      if (!total) {
        finalTotal = inputQuantity * (itemPrice || 0);
      }

    } else {
      // =========================================================================
      // LUỒNG 2: THANH TOÁN QUA GIỎ HÀNG
      // =========================================================================
      const cartId = parseInt(cart_id);
      if (!cartId) {
        await transaction.rollback();
        return res.status(400).json({ message: "Thiếu thông tin giỏ hàng hợp lệ" });
      }

      // Đọc giỏ hàng và include cả sản phẩm lẫn biến thể nếu có trong bảng cart_items
      const cart = await db.carts.findByPk(cartId, {
        include: [
          {
            model: db.cart_items,
            as: "cart_items",
            include: [
              { model: db.products, as: "products" },
              // 🔥 Kiểm tra nếu bảng cart_items của bạn có lưu kèm variant_id/product_variant_value_id thì include vào đây
              ...(VariantModel ? [{ model: VariantModel, as: "product_variant_values", required: false }] : [])
            ],
          },
        ],
        transaction,
      });

      if (!cart || !cart.cart_items || cart.cart_items.length === 0) {
        await transaction.rollback();
        return res.status(400).json({ message: "Giỏ hàng không hợp lệ hoặc đang trống" });
      }

      // Kiểm tra tính hợp lệ số lượng kho hàng loạt
      for (const item of cart.cart_items) {
        if (!item.products) {
          await transaction.rollback();
          return res.status(404).json({ message: `Sản phẩm ID ${item.product_id} không tồn tại` });
        }

        // Nếu item giỏ hàng có chọn biến thể cụ thể (Cột check tuỳ thuộc vào cách bạn đặt tên trong bảng cart_items, ví dụ item.variant_id)
        const itemVariant = item.product_variant_values || item.variant; 
        if (itemVariant) {
          if (itemVariant.stock < item.quanity) {
            await transaction.rollback();
            return res.status(400).json({ message: `Phân loại của sản phẩm ${item.products.name} không đủ số lượng (Còn lại: ${itemVariant.stock})` });
          }
        } else {
          // Nếu là sản phẩm thường không biến thể
          if (item.products.quanity < item.quanity) {
            await transaction.rollback();
            return res.status(400).json({ message: `Sản phẩm ${item.products.name} không đủ số lượng` });
          }
        }
      }

      // Tính tổng tiền tự động nếu FE không truyền lên total
      if (!total) {
        finalTotal = cart.cart_items.reduce((sum, item) => {
          // Lấy giá biến thể nếu có, ngược lại lấy giá sản phẩm gốc
          const currentPrice = item.product_variant_values?.price || item.products.price || 0;
          return sum + item.quanity * currentPrice;
        }, 0);
      }

      // Đẩy thông tin sang mảng Order Detail tạm thời
      orderDetails = cart.cart_items.map((item) => ({
        product_id: item.product_id,
        variant_id: item.product_variant_values?.id || item.variant_id || null,
        quantity: item.quanity,
        price: item.product_variant_values?.price || item.products.price,
      }));

      // Thực thi trừ kho hàng loạt & Xóa giỏ hàng
      for (const item of cart.cart_items) {
        const itemVariant = item.product_variant_values || item.variant;
        if (itemVariant && VariantModel) {
          // Trừ kho bảng biến thể
          await VariantModel.update(
            { stock: itemVariant.stock - item.quanity },
            { where: { id: itemVariant.id }, transaction }
          );
        } else {
          // Trừ kho bảng sản phẩm gốc
          await db.products.update(
            { quanity: item.products.quanity - item.quanity },
            { where: { id: item.product_id }, transaction }
          );
        }
      }

      await db.cart_items.destroy({ where: { cart_id: cartId }, transaction });
    }

    // =========================================================================
    // TẠO ĐƠN HÀNG TRÊN DATABASE
    // =========================================================================
    const orderUserId = user_id ? Number(user_id) : null;
    const orderSessionId = session_id || "session_direct";

    const newOrder = await db.orders.create(
      {
        session_id: orderSessionId,
        user_id: orderUserId,
        status: 1, // 1: Chờ xử lý / Mới tạo
        total: Number(finalTotal),
        note: note || null,
        phone: phone || null,
        address: address || null,
      },
      { transaction }
    );

    // Chuẩn bị mảng bản ghi để ghi vào bảng order_details
    const finalOrderDetails = orderDetails.map((detail) => ({
      order_id: newOrder.id,
      product_id: detail.product_id,
      variant_id: detail.variant_id || null, // Lưu vết ID màu sắc/dung lượng khách mua nếu bảng lưu trữ có cột này
      price: detail.price,
      quantity: detail.quantity || 1,
    }));

    const matchedKey = Object.keys(db).find((key) => {
      const normalized = key.toLowerCase().replace(/[-_]/g, "");
      return normalized === "orderdetail" || normalized === "orderdetails";
    });

    if (matchedKey && db[matchedKey] && typeof db[matchedKey].bulkCreate === "function") {
      await db[matchedKey].bulkCreate(finalOrderDetails, { transaction });
    } else {
      await transaction.rollback();
      return res.status(500).json({
        message: "Checkout thất bại do lỗi cấu hình tên Model Chi tiết đơn hàng",
      });
    }

    await transaction.commit();
    return res.status(200).json({
      message: isBuyNow ? "Mua trực tiếp thành công!" : "Thanh toán thành công!",
      data: { order_id: newOrder.id },
    });

  } catch (error) {
    await transaction.rollback();
    console.error("CRASH TẠI BACKEND CHECKOUT:", error);
    return res.status(500).json({
      message: "Checkout thất bại do lỗi hệ thống",
      error: error.message,
    });
  }
}





async function deleteCart(req, res) {
  const { id } = req.params;

  const deleted = await db.carts.destroy({
    where: { id },
  });

  if (deleted) {
    return res.status(200).json({
      message: "Xóa giỏ hàng thành công",
    });
  }

  return res.status(404).json({
    message: "Giỏ hàng không tồn tại",
  });
}

module.exports = {
  getCarts,
  getCartById,
  insertCart,
  deleteCart,
  checkoutCart,
};

