sourcesContent:
const Sequelize = require("sequelize");
const db = require("../models");

// 1. LẤY DANH SÁCH MỤC TRONG GIỎ (GET /api/cart-items/carts/:cart_id)
async function getCartItembyCartId(req, res) {
  try {
    const { cart_id } = req.params;

    const cartItems = await db.cart_items.findAll({
      where: { cart_id },
      attributes: [
        "id",
        "cart_id",
        "product_id",
        "product_variant_value_id",
        "quanity",
        "created_at",
        "updated_at",
      ],
      include: [
        {
          model: db.products,
          as: "products",
        },
        {
          model: db.product_variant_values,
          as: "product_variant_values",
        },
      ],
    });

    return res.status(200).json({
      message: "Lấy danh sách mục trong giỏ hàng thành công",
      data: cartItems,
    });
  } catch (error) {
    console.error("Lỗi getCartItembyCartId:", error);
    return res
      .status(500)
      .json({ message: "Lỗi hệ thống máy chủ", error: error.message });
  }
}

// 2. THÊM SẢN PHẨM VÀO GIỎ HÀNG (POST /api/cart-items) - ĐÃ SỬA LỖI KHÓA NGOẠI 🌟
// 2. THÊM SẢN PHẨM VÀO GIỎ HÀNG (POST /api/cart-items) - CẬP NHẬT TRẢ VỀ CART_ID THỰC TẾ 🌟
// 2. THÊM MỤC MỚI VÀO GIỎ HÀNG (SỬA LỖI TRUYỀN SAI BIẾN PRODUCT_ID)
async function insertCartItem(req, res) {
  try {
    // Bóc tách đúng tên trường được gửi từ Frontend (ProductDetail.jsx)
    const { productId, quantity, productVariantValueId } = req.body;
    
    // Lấy user_id từ token hoặc lấy tạm từ body / mặc định để tìm giỏ
    const user_id = req.user?.id || req.body.user_id || 1;

    // ÉP KIỂU VÀ PHÒNG BỊ BIẾN: Tránh tuyệt đối việc lấy nhầm số lượng quantity (1) vào productId
    const final_product_id = parseInt(productId || req.body.product_id);
    const final_quantity = parseInt(quantity) || 1;
    const final_variant_id = productVariantValueId ? parseInt(productVariantValueId) : null;

    // Kiểm tra an toàn dữ liệu đầu vào
    if (!final_product_id || isNaN(final_product_id)) {
      return res.status(400).json({
        message: "Thêm vào giỏ hàng thất bại",
        error: "productId không hợp lệ hoặc bị null từ client gửi lên!"
      });
    }

    // Tự động tìm hoặc tạo giỏ hàng cho User (để lấy được đúng cart_id thực tế)
    const [cart] = await db.carts.findOrCreate({
      where: { user_id },
      defaults: {
        user_id,
        session_id: req.body.session_id || `session_${user_id}`,
      },
    });

    // Kiểm tra xem sản phẩm cùng biến thể này đã có sẵn trong giỏ của user này chưa
    const existingItem = await db.cart_items.findOne({
      where: {
        cart_id: cart.id,
        product_id: final_product_id,
        product_variant_value_id: final_variant_id,
      },
    });

    if (existingItem) {
      // Nếu có rồi, cộng dồn số lượng vào cột 'quanity' đúng chính tả của DB bạn
      existingItem.quanity = Number(existingItem.quanity || 0) + final_quantity;
      await existingItem.save();
      return res.status(200).json({
        message: "Cập nhật số lượng sản phẩm trong giỏ hàng thành công",
        data: existingItem,
      });
    }

    // Nếu chưa có, tiến hành tạo bản ghi mới với giá trị chính xác tuyệt đối
    const newCartItem = await db.cart_items.create({
      cart_id: cart.id,
      product_id: final_product_id,               // Đã fix: Giá trị sẽ là 65 thay vì bị gán bằng số lượng 1
      product_variant_value_id: final_variant_id, // Có thể mang ID biến thể hoặc null
      quanity: final_quantity,                    // Số lượng mua thực tế
    });

    return res.status(201).json({
      message: "Thêm vào giỏ hàng thành công",
      data: newCartItem,
    });
  } catch (error) {
    console.error("❌ Lỗi thêm vào giỏ hàng tại CartItemController:", error);
    return res
      .status(500)
      .json({ message: "Lỗi máy chủ khi ghi dữ liệu", error: error.message });
  }
}
// 3. XÓA MỤC KHỎI GIỎ HÀNG
async function deleteCartItem(req, res) {
  try {
    const { id } = req.params;
    await db.cart_items.destroy({ where: { id } });
    return res.status(200).json({ message: "Xóa thành công" });
  } catch (error) {
    return res.status(500).json({ message: "Lỗi hệ thống" });
  }
}

// 4. CẬP NHẬT SỐ LƯỢNG TẠI TRANG GIỎ HÀNG
async function updateCartItem(req, res) {
  try {
    const { id } = req.params;
    const { quanity } = req.body;
    await db.cart_items.update({ quanity }, { where: { id } });
    return res.status(200).json({ message: "Cập nhật thành công" });
  } catch (error) {
    return res.status(500).json({ message: "Lỗi hệ thống" });
  }
}

// 5. LẤY DANH SÁCH CHO ADMIN
async function getCartItems(req, res) {
  try {
    const items = await db.cart_items.findAll({
      attributes: [
        "id",
        "cart_id",
        "product_id",
        "quanity",
        "created_at",
        "updated_at",
      ],
      include: [{ model: db.products, as: "products" }],
    });
    return res.status(200).json({ data: items });
  } catch (error) {
    return res.status(500).json({ message: "Lỗi hệ thống" });
  }
}

module.exports = {
  getCartItems,
  insertCartItem,
  deleteCartItem,
  updateCartItem,
  getCartItembyCartId,
};

