var fs = require("fs");
var path = require("path");
var Sequelize = require("sequelize");
var process = require("process");
var basename = path.basename(__filename);
var env = process.env.NODE_ENV || "development";
var config = require(__dirname + "/../config/config.js")[env];
var db = {};
var sequelize;
if (config.use_env_variable) {
  sequelize = new Sequelize(process.env[config.use_env_variable], config);
} else {
  sequelize = new Sequelize(config.database, config.username, config.password, config);
}
fs.readdirSync(__dirname).filter(function (file) {
  return file.indexOf(".") !== 0 && file !== basename && file.slice(-3) === ".js" && file.indexOf(".test.js") === -1;
}).forEach(function (file) {
  try {
    var modelImport = require(path.join(__dirname, file));

    // Hỗ trợ cả ES Modules (export default) và CommonJS (module.exports)
    var modelFunction = modelImport["default"] || modelImport;
    if (typeof modelFunction === "function") {
      var model = modelFunction(sequelize, Sequelize.DataTypes);
      db[model.name] = model;
    } else {
      // In ra cảnh báo nếu file không đúng định dạng model chuẩn
      console.warn("\u26A0\uFE0F C\u1EA3nh b\xE1o Sequelize: File \"".concat(file, "\" kh\xF4ng export \u0111\xFAng function n\xEAn \u0111\xE3 b\u1ECB b\u1ECF qua."));
    }
  } catch (error) {
    // In ra chi tiết lỗi của file đó để bạn dễ dàng sửa code
    console.error("\u274C L\u1ED7i nghi\xEAm tr\u1ECDng khi n\u1EA1p file model \"".concat(file, "\":"), error.message);
