const Sequelize = require("sequelize");
const db = require("../models");

const InsertProduct = require("../dtos/requests/order/InsertOrder");
const UpdateOrder = require("../dtos/requests/order/UpdateOrder");
const Op = Sequelize.Op;
const { OrderStatus } = require("../constants");

function findModel(targetName) {
  if (!db) return null;
  const keys = Object.keys(db);
  const normalizedTarget = targetName.toLowerCase().replace(/[^a-z0-9]/g, "");

  const matchedKey = keys.find((key) => {
    const normalizedKey = key.toLowerCase().replace(/[^a-z0-9]/g, "");
    return (
      normalizedKey === normalizedTarget ||
      normalizedKey === normalizedTarget + "s" ||
      normalizedTarget === normalizedKey + "s"
    );
  });

  return matchedKey ? db[matchedKey] : null;
}

// 1. Lấy danh sách đơn hàng
async function getOrders(req, res) {
  try {
    const {
      search = "",
      page = 1,
      limit = 10,
      status,
      user_id,
      manager_id,
    } = req.query;

    const pageSize = parseInt(limit) || 10;
    const offset = (parseInt(page) - 1) * pageSize;

    let whereClause = {};

    if (search.trim() !== "") {
      whereClause = {
        [Op.or]: [{ note: { [Op.like]: `%${search}%` } }],
      };
    }

    if (status) {
      whereClause.status = status;
    }

    if (user_id) {
      whereClause.user_id = user_id;
    }

    const UserModel = findModel("user") || findModel("users");
    const OrderDetailModel =
      findModel("order_detail") || findModel("orderdetail");
    const ProductModel = findModel("products") || findModel("product");
    const ProductVariantValueModel =
      findModel("product_variant_values") || findModel("productvariantvalue");
    const OrdersModel = findModel("orders") || findModel("order");

    if (!OrdersModel) {
      return res.status(500).json({
        message: "Lỗi hệ thống: Không tìm thấy cấu hình Model cho bảng orders.",
      });
    }

    const includeArr = [
      UserModel && {
        model: UserModel,
        as: "User",
        attributes: ["id", "name", "email", "phone"],
        required: false,
      },
      OrderDetailModel && {
        model: OrderDetailModel,
        as: "order_detail",
        required: false,
        include: [
          ProductModel && {
            model: ProductModel,
            as: "products",
            attributes: ["id", "name", "image", "price", "user_id"],
            required: false,
          },
          ProductVariantValueModel && {
            model: ProductVariantValueModel,
            as: "product_variant_values",
            attributes: [
              "id",
              "product_id",
              "price",
              "old_price",
              "stock",
              "sku",
              "image_url",
            ],
            required: false,
          },
        ].filter(Boolean),
      },
    ].filter(Boolean);

    if (manager_id && manager_id !== "null" && manager_id !== "undefined") {
      const parsedManagerId = parseInt(manager_id);
      if (!isNaN(parsedManagerId)) {
        whereClause["$order_detail.products.user_id$"] = parsedManagerId;
      }
    }

    const { rows: orders, count: totalOrders } =
      await OrdersModel.findAndCountAll({
        where: whereClause,
        include: includeArr,
        limit: pageSize,
        offset: offset,
        distinct: true,
        subQuery: false,
        order: [["id", "DESC"]],
      });

    const formattedOrders = orders.map((order) => {
      const plainOrder = order.get({ plain: true });

      if (Array.isArray(plainOrder.order_detail)) {
        plainOrder.order_detail = plainOrder.order_detail.map((detail) => {
          if (!detail.product_variant_values) {
            detail.product_variant_values = {
              id: detail.product_variant_value_id || null,
              sku: detail.products?.sku || `PROD-${detail.product_id}`,
              variant_name: "Mặc định",
              price: detail.price || detail.products?.price || 0,
              image_url: detail.products?.image || null,
            };
          }
          return detail;
        });
      }

      return plainOrder;
    });

    return res.status(200).json({
      message: "Lấy danh sách đơn hàng thành công",
      data: formattedOrders,
      pagination: {
        totalOrders,
        currentPage: parseInt(page),
        totalPages: Math.ceil(totalOrders / pageSize),
      },
    });
  } catch (error) {
    console.error("Lỗi hệ thống tại getOrders: ", error);
    return res.status(500).json({
      message: "Đã xảy ra lỗi hệ thống khi lấy danh sách đơn hàng",
      error: error.message,
    });
  }
}

// 2. Lấy chi tiết đơn hàng
async function getOrderById(req, res) {
  try {
    const { id } = req.params;
    const OrderDetailModel =
      findModel("order_detail") || findModel("orderdetail");
    const ProductModel = findModel("products") || findModel("product");
    const ProductVariantValueModel =
      findModel("product_variant_values") || findModel("productvariantvalue");
    const OrdersModel = findModel("orders") || findModel("order");

    if (!OrdersModel) {
      return res.status(500).json({
        message: "Lỗi hệ thống: Không tìm thấy cấu hình Model cho bảng orders.",
      });
    }

    const includeArr = [];
    if (OrderDetailModel) {
      includeArr.push({
        model: OrderDetailModel,
        as: "order_detail",
        include: [
          ProductModel && {
            model: ProductModel,
            as: "products",
            attributes: ["id", "name", "image", "price"],
          },
          ProductVariantValueModel && {
            model: ProductVariantValueModel,
            as: "product_variant_values",
          },
        ].filter(Boolean),
      });
    }

    const order = await OrdersModel.findByPk(id, {
      include: includeArr,
    });

    if (!order) {
      return res.status(404).json({ message: "Không tìm thấy đơn hàng" });
    }

    return res.status(200).json({
      message: "Lấy đơn hàng thành công",
      data: order,
    });
  } catch (error) {
    console.error("Lỗi hệ thống tại getOrderById: ", error);
    return res.status(500).json({
      message: "Đã xảy ra lỗi hệ thống khi lấy chi tiết đơn hàng",
      error: error.message,
    });
  }
}

// 🚀 3. TẠO ĐƠN HÀNG MỚI (ĐÃ SỬA CHUẨN DỮ LIỆU ĐỂ TRỪ KHO CHÍNH XÁC)
// 🚀 TẠO ĐƠN HÀNG VÀ TRỪ KHO (CẬP NHẬT TỔNG KHO QUANITY & STOCK BIẾN THỂ)
async function createOrder(req, res) {
  const transaction = await db.sequelize.transaction();
  try {
    const OrdersModel = findModel("orders") || findModel("order");
    const OrderDetailModel =
      findModel("order_detail") || findModel("orderdetail");

    const {
      user_id,
      total,
      note,
      phone,
      address,
      product_id,
      productId,
      quantity,
      quanity,
      variant_id,
      product_variant_value_id,
      items,
      cart_id,
    } = req.body;

    const directProductId = product_id || productId;

    // 1. Tạo đơn hàng
    const newOrder = await OrdersModel.create(
      {
        user_id: Number(user_id),
        total: Number(total),
        note,
        phone,
        address,
        status: OrderStatus.PENDING || 1,
        session_id: "session_direct",
      },
      { transaction }
    );

    let rawItems = [];

    // Phân loại danh sách mặt hàng mua
    if (items && Array.isArray(items) && items.length > 0) {
      rawItems = items;
    } else if (directProductId) {
      rawItems = [
        {
          product_id: Number(directProductId),
          quantity: Number(quantity || quanity || 1),
          price: Number(total),
          product_variant_value_id:
            product_variant_value_id || variant_id
              ? Number(product_variant_value_id || variant_id)
              : null,
        },
      ];
    } else if (cart_id) {
      const CartItemModel =
        findModel("cart_item") || findModel("cartitem") || findModel("cart_items");
      if (CartItemModel) {
        const dbCartItems = await CartItemModel.findAll({
          where: { cart_id: Number(cart_id) },
          transaction,
        });

        rawItems = dbCartItems.map((ci) => ({
          product_id: Number(ci.product_id),
          product_variant_value_id:
            ci.product_variant_value_id || ci.variant_id
              ? Number(ci.product_variant_value_id || ci.variant_id)
              : null,
          quantity: Number(ci.quantity || ci.quanity || 1),
          price: Number(ci.price || ci.applied_price || 0),
        }));
      }
    }

    // 2. Tạo Order Detail & TRỪ TỒN KHO
    for (const item of rawItems) {
      const targetProductId = Number(item.product_id || item.productId);
      const targetVariantId =
        item.product_variant_value_id || item.variant_id || item.variantId
          ? Number(item.product_variant_value_id || item.variant_id || item.variantId)
          : null;

      const targetQty = Math.max(1, Number(item.quantity || item.quanity || 1));

      if (!targetProductId) continue;

      // A. Tạo chi tiết đơn hàng
      await OrderDetailModel.create(
        {
          order_id: newOrder.id,
          product_id: targetProductId,
          product_variant_value_id: targetVariantId,
          quantity: targetQty,
          price: item.price || 0,
        },
        { transaction }
      );

      // B. BẮT BUỘC TRỪ TỔNG KHO CỦA SẢN PHẨM GỐC (`quanity`)
      await db.sequelize.query(
        `UPDATE products SET quanity = quanity - :qty WHERE id = :pId`,
        {
          replacements: { qty: targetQty, pId: targetProductId },
          transaction,
        }
      );

      // C. NẾU CÓ BIẾN THỂ -> TRỪ THÊM KHO RIÊNG CỦA BIẾN THỂ ĐÓ (`stock`)
      if (targetVariantId) {
        await db.sequelize.query(
          `UPDATE product_variant_values SET stock = stock - :qty WHERE id = :vId`,
          {
            replacements: { qty: targetQty, vId: targetVariantId },
            transaction,
          }
        );
      }
    }

    // 3. Xóa giỏ hàng nếu mua từ Giỏ
    if (cart_id) {
      const CartItemModel =
        findModel("cart_item") || findModel("cartitem") || findModel("cart_items");
      if (CartItemModel) {
        await CartItemModel.destroy({
          where: { cart_id: Number(cart_id) },
          transaction,
        });
      }
    }

    await transaction.commit();

    return res.status(201).json({
      message: "Tạo đơn hàng và trừ kho thành công!",
      data: newOrder,
    });
  } catch (error) {
    await transaction.rollback();
    console.error("❌ Lỗi tạo đơn hàng:", error);
    return res.status(500).json({
      message: "Lỗi tạo đơn hàng",
      error: error.message,
    });
  }
}

// 🚀 4. HỦY ĐƠN HÀNG (CỘNG TRẢ LẠI TỒN KHO)
// 🚀 HỦY ĐƠN HÀNG VÀ HOÀN TỒN KHO CHUẨN XÁC
async function deleteOrder(req, res) {
  const transaction = await db.sequelize.transaction();
  try {
    const { id } = req.params;
    const OrdersModel = findModel("orders") || findModel("order");
    const OrderDetailModel =
      findModel("order_detail") || findModel("orderdetail");

    if (!OrdersModel) {
      await transaction.rollback();
      return res.status(500).json({
        message: "Lỗi hệ thống: Không tìm thấy cấu hình Model cho bảng orders.",
      });
    }

    // 1. Tìm đơn hàng
    const order = await OrdersModel.findByPk(id);

    if (!order) {
      await transaction.rollback();
      return res.status(404).json({ message: "Đơn hàng không tồn tại" });
    }

    const cancelledStatus = OrderStatus.CANCELLED || 5;

    // 2. Nếu đơn chưa bị hủy trước đó -> Tiến hành cộng hoàn lại tồn kho
    if (
      String(order.status) !== String(cancelledStatus) &&
      String(order.status) !== "0"
    ) {
      // Tìm danh sách chi tiết đơn hàng (truy vấn trực tiếp để tránh lỗi alias Sequelize)
      let details = [];
      if (OrderDetailModel) {
        details = await OrderDetailModel.findAll({
          where: { order_id: id },
          transaction,
        });
      }

      for (const detail of details) {
        const qty = Math.max(1, Number(detail.quantity || detail.quanity || 1));
        const pId = Number(detail.product_id);
        const vId = detail.product_variant_value_id
          ? Number(detail.product_variant_value_id)
          : null;

        // A. BẮT BUỘC CỘNG TRẢ LẠI TỔNG KHO SẢN PHẨM GỐC (`products.quanity`)
        if (pId) {
          await db.sequelize.query(
            `UPDATE products SET quanity = quanity + :qty WHERE id = :pId`,
            {
              replacements: { qty, pId },
              transaction,
            }
          );
        }

        // B. NẾU CÓ BIẾN THỂ -> CỘNG TRẢ LẠI KHO RIÊNG CỦA BIẾN THỂ (`product_variant_values.stock`)
        if (vId) {
          await db.sequelize.query(
            `UPDATE product_variant_values SET stock = stock + :qty WHERE id = :vId`,
            {
              replacements: { qty, vId },
              transaction,
            }
          );
        }
      }
    }

    // 3. Cập nhật trạng thái đơn hàng thành Đã hủy
    await OrdersModel.update(
      { status: cancelledStatus },
      { where: { id }, transaction }
    );

    await transaction.commit();
    return res.status(200).json({
      message: "Hủy đơn hàng và hoàn tồn kho thành công!",
    });
  } catch (error) {
    await transaction.rollback();
    console.error("Lỗi hệ thống tại deleteOrder: ", error);
    return res.status(500).json({
      message: "Đã xảy ra lỗi khi xử lý hủy đơn hàng",
      error: error.message,
    });
  }
}

// 🚀 5. CẬP NHẬT TRẠNG THÁI ĐƠN HÀNG (CỘNG TRẢ KHO NẾU ĐỔI THÀNH HỦY)
async function updateOrder(req, res) {
  const transaction = await db.sequelize.transaction();
  try {
    const { id } = req.params;
    const { status } = req.body;
    const OrdersModel = findModel("orders") || findModel("order");
    const OrderDetailModel =
      findModel("order_detail") || findModel("orderdetail");
    const ProductModel = findModel("products") || findModel("product");
    const ProductVariantValueModel =
      findModel("product_variant_values") || findModel("productvariantvalue");

    if (!OrdersModel) {
      return res.status(500).json({
        message: "Lỗi hệ thống: Không tìm thấy cấu hình Model cho bảng orders.",
      });
    }

    const order = await OrdersModel.findByPk(id, {
      include: OrderDetailModel
        ? [{ model: OrderDetailModel, as: "order_detail" }]
        : [],
    });

    if (!order) {
      await transaction.rollback();
      return res.status(404).json({ message: "Đơn hàng không tồn tại" });
    }

    const cancelledStatus = OrderStatus.CANCELLED || 5;
    const isNewStatusCancelled =
      String(status) === String(cancelledStatus) || String(status) === "0";
    const isOldStatusCancelled =
      String(order.status) === String(cancelledStatus) ||
      String(order.status) === "0";

    // Nếu đơn đổi từ trạng thái bình thường sang "ĐÃ HỦY" -> Hoàn tồn kho
    if (isNewStatusCancelled && !isOldStatusCancelled) {
      const details = order.order_detail || [];
      for (const detail of details) {
        const qty = Number(detail.quantity || detail.quanity || 1);

        if (detail.product_variant_value_id && ProductVariantValueModel) {
          await ProductVariantValueModel.increment("stock", {
            by: qty,
            where: { id: detail.product_variant_value_id },
            transaction,
          });
        }

        if (detail.product_id && ProductModel) {
          if (ProductModel.rawAttributes.quanity) {
            await ProductModel.increment("quanity", {
              by: qty,
              where: { id: detail.product_id },
              transaction,
            });
          } else if (ProductModel.rawAttributes.stock) {
            await ProductModel.increment("stock", {
              by: qty,
              where: { id: detail.product_id },
              transaction,
            });
          }
        }
      }
    }

    await OrdersModel.update(req.body, {
      where: { id },
      transaction,
    });

    await transaction.commit();
    return res.status(200).json({
      message: "Cập nhật đơn hàng thành công",
    });
  } catch (error) {
    await transaction.rollback();
    console.error("Lỗi hệ thống tại updateOrder: ", error);
    return res.status(500).json({
      message: "Đã xảy ra lỗi khi cập nhật đơn hàng",
      error: error.message,
    });
  }
}

module.exports = {
  getOrders,
  getOrderById,
  createOrder,
  deleteOrder,
  updateOrder,
  // Thêm các alias để dù bên approuter gọi kiểu nào cũng không bao giờ bị undefined
  updateOrderStatus: updateOrder,
};

