  const API_PREFIX = `http://${os.hostname()}:${process.env.PORT || 3000}/api`;

  // convert sang url
  const imageUrls = files.map((file) => `${API_PREFIX}/images/${file}`);

  return res.status(200).json({
    message: "Lấy danh sách ảnh thành công",
    total: imageUrls.length,
    files: imageUrls,
  });
}

