sourcesContent:
const { getUserFromToken } = require("../helpers/TokenHelper");

const requireRoles = (roleRequired) => async (req, res, next) => {
  try {
    // Gọi hàm helper gốc (hàm này có thể throw lỗi nếu token hết hạn/lỗi)
    const user = await getUserFromToken(req);

    // Trường hợp lọt qua helper nhưng không tìm thấy user hợp lệ
    if (!user) {
      return res.status(401).json({
        success: false,
        message: "Không thể xác thực người dùng",
      });
    }

    console.log("user.role =", user.role);
    console.log("roleRequired =", roleRequired);

    // Kiểm tra tài khoản bị khóa
    if (user.is_locked === 1) {
      return res.status(403).json({
        message: "Tài khoản này đã bị khóa",
      });
    }

    // Kiểm tra phân quyền
    if (!roleRequired.includes(user.role)) {
      return res.status(403).json({
        message: "Bạn không có quyền truy cập",
      });
    }

    // Lưu thông tin user vào req và đi tiếp
    req.user = user;
    return next();
  } catch (error) {
    // BẮT MỌI LỖI THROW TỪ HELPER TẠI ĐÂY (TokenExpiredError, InvalidToken,...)
    console.error("JWT Middleware Error:", error.message);

    // Phân loại lỗi để trả về thông báo chính xác cho frontend
    let errorMessage = "Phiên đăng nhập không hợp lệ hoặc đã hết hạn";
    let errorCode = "Unauthorized";

    if (
      error.name === "TokenExpiredError" ||
      error.message.includes("hết hạn")
    ) {
      errorCode = "TokenExpiredError";
      errorMessage = "Phiên đăng nhập của bạn đã hết hạn!";
    } else if (error.message.includes("mật khẩu đã thay đổi")) {
      errorCode = "PasswordChanged";
      errorMessage = "Mật khẩu đã được thay đổi, vui lòng đăng nhập lại!";
    }

    return res.status(401).json({
      success: false,
      code: errorCode,
      message: errorMessage,
    });
  }
};

module.exports = {
  requireRoles,
};

